import{_ as a,o as _,a as e,b as c}from"./app.UgfkfLuP.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"随路量化与随路ReLU场景组合","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","lastUpdated":1791622466000}'),r={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md"};function d(o,t,i,p,n,s){return _(),e("div",null,[...t[0]||(t[0]=[c('<div><article class="markdown-body"><h1>随路量化与随路ReLU场景组合</h1><p>矩阵搬出支持多种随路量化与随路ReLU的组合，常用的不激活/Normal ReLU组合参考下表，Scalar/Vector扩展组合见后文。</p><p>阅读本表前，可先了解<a href="accompanying_quantization.html">随路量化</a>中的模式、Scalar/Vector粒度及参数编码，以及<a href="accompanying_relu.html">随路ReLU</a>中的激活模式。表中的<code>QUANT_PRE</code>是Scalar量化参数，<code>Quant_PRE_ADDR[i]</code>是Fixpipe Buffer中第i列的Vector量化参数；它们与搬出接口中选择量化模式的参数不是同一含义。</p><p>量化系数不能为inf、nan或非规格化数。下表描述非负/负输入所使用的系数来源，最终输出还包含所选模式的类型转换、舍入、饱和以及有效Offset处理，不能仅用系数表替代完整的量化算法。</p><div data-filter="950,A3,910b"><p>随路量化与随路ReLU的组合情况如下表所示：</p><div data-filter="A3,910b"><p><strong>表1</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>quant_pre / relu_pre</th><th>0（不激活）</th><th>1（Normal ReLU）</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE</td><td>M1=QUANT_PRE[31:0]<br>M2=QUANT_PRE[31:0]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:0]<br>M2=0<br>M1为量化参数、M2为NORMAL系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=Quant_PRE_ADDR[i][31:0]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=0<br>M1为量化参数，M2为NORMAL系数，i为原始矩阵的列索引</td></tr></tbody></table></div><div data-filter="950"><p><strong>表2</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>quant_pre_mode / relu_pre_mode</th><th>NONE</th><th>NORMAL</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE<br>•QF322FP8_PRE<br>•QF322HIF8_PRE<br>•QF322HIF8_PRE_HYBRID<br>•QS322BF16_PRE<br>•QF322F16_PRE<br>•QF322BF16_PRE<br>•QF322F32_PRE</td><td>M1=QUANT_PRE[31:13]<br>M2=QUANT_PRE[31:13]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:13]<br>M2=0<br>M1为量化参数、M2为NORMAL系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE<br>•VQF322FP8_PRE<br>•VQF322HIF8_PRE<br>•VQF322HIF8_PRE_HYBRID<br>•VQS322BF16_PRE<br>•VQF322F16_PRE<br>•VQF322BF16_PRE<br>•VQF322F32_PRE</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=Quant_PRE_ADDR[i][31:13]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=0<br>M1为量化参数，M2为NORMAL系数，i为原始矩阵的列索引</td></tr></tbody></table></div></div><p>注：M1为原始数据非负时使用的随路系数，M2为原始数据为负数时使用的随路系数。</p><p><strong>配置接口与模式的对应关系：</strong></p><table><thead><tr><th>配置对象</th><th>C API入口</th><th>使用要点</th></tr></thead><tbody><tr><td>Scalar量化系数</td><td><a href="../cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a></td><td>按当前架构选择量化系数配置重载。</td></tr><tr><td>Vector量化/激活参数</td><td><a href="../cube_compute_load/asc_copy_l12fb.html">asc_copy_l12fb</a> → <a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a></td><td>先搬入对应参数区，再设置量化或激活地址索引；两类索引单位分别为128B、64B。</td></tr><tr><td>搬出模式</td><td><a href="../cube_compute_store/asc_copy_l0c2gm.html">asc_copy_l0c2gm</a>、<a href="../cube_compute_store/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a></td><td>选择当前架构的量化/激活模式，并核对支持的dtype组合。</td></tr></tbody></table><div data-filter="A3,910b"><p>Atlas A3系列产品和Atlas A2系列产品的Scalar量化传入打包的<code>uint64_t config</code>。</p></div><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品还提供<code>scale</code>、<code>offset</code>和<code>is_signed</code>分项配置重载。</p></div><div data-filter="950"><p>对于Ascend 950PR&amp;950DT系列产品，除表2的<code>NONE</code>与<code>NORMAL</code>外，<a href="../../defs/enum/asc_relu_pre_mode.html">asc_relu_pre_mode</a>还提供以下激活参数来源：</p><table><thead><tr><th>激活模式</th><th>参数准备</th><th>说明</th></tr></thead><tbody><tr><td><code>SCALAR</code></td><td><a href="../cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a></td><td>全矩阵共享Scalar激活系数。</td></tr><tr><td><code>VECTOR</code></td><td><a href="../cube_compute_load/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb（Ascend 950PR&amp;950DT系列产品）</a>及<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>的<code>relu_pre_addr</code></td><td>每个N通道读取对应的Vector激活参数。</td></tr></tbody></table><p>这些模式描述参数来源，并不表示可以与全部量化类型、输出布局任意组合。Ascend 950PR&amp;950DT系列产品搬出接口中的随路功能组合图、<code>enable_clip_relu_pre</code>及相关约束见<a href="../cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm（Ascend 950PR&amp;950DT系列产品）</a>；搬出到UB还需遵循<a href="L0C_to_UB_dual_target_mode.html">双目标模式</a>对随路功能的限制。</p></div><p><strong>量化算法与完整样例：</strong></p><p>以下链接给出C API样例中的量化算法示意，阅读时对照当前架构的参数编码和模式约束；脚本中的固定规格、系数及模式不能视为所有接口组合的定义。</p><ul><li>int32_t到int8_t/uint8_t：<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/scripts/gen_data_s322s8.py">(V)REQ8量化算法</a>。</li><li>int32_t到half：<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/scripts/gen_data_s322f16.py">(V)DEQF16量化算法</a>。</li><li>float到int8_t/uint8_t：<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/scripts/gen_data_f322s8.py">(V)QF322B8_PRE量化算法</a>。</li></ul><p>实际API调用流程参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/README.md">asc_copy_l0c2gm样例</a>：场景4、5为Scalar/Vector量化，场景6为Normal ReLU。</p></article></div>',1)])])}const m=a(r,[["render",d]]);export{b as __pageData,m as default};
